int snd_timer_user_select(struct file *file, struct snd_timer_select __user *_tselect) {
    struct snd_timer_user *timer = file->private_data;
    struct snd_timer *t;
    int err;

    if (timer->timer)
        snd_timer_close(timer->timer);

    timer->timer = NULL;
    timer->queue = NULL;

    err = get_user(timer->tselect.resolution.tv_sec, &_tselect->resolution.tv_sec);
    if (err)
        return err;

    err = get_user(timer->tselect.resolution.tv_nsec, &_tselect->resolution.tv_nsec);
    if (err)
        return err;

    err = get_user(timer->tselect.ticks, &_tselect->ticks);
    if (err)
        return err;

    err = get_user(timer->tselect.card, &_tselect->card);
    if (err)
        return err;

    err = get_user(timer->tselect.device, &_tselect->device);
    if (err)
        return err;

    err = get_user(timer->tselect.subdevice, &_tselect->subdevice);
    if (err)
        return err;

    t = snd_timer_new(timer->tselect.card, "User Timer", &timer->tselect, NULL);
    if (!t)
        return -ENOMEM;

    timer->timer = t;
    t->private_data = timer;

    t->callback = snd_timer_user_callback;
    t->private_free = snd_timer_user_free;

    t->flags |= SNDRV_TIMER_FLG_FAST;

    return 0;
}

#include <linux/fs.h>
#include <linux/slab.h>
#include <sound/timer.h>

int select_and_init_timer(struct file *file, struct snd_timer_select __user *_tselect) {
    struct snd_timer *timer;
    struct snd_timer_select tselect;
    struct snd_timer_id *tid;
    int err;

    if (copy_from_user(&tselect, _tselect, sizeof(tselect)))
        return -EFAULT;

    tid = &tselect.id;

    timer = snd_timer_new(file->private_data, tid, 0);
    if (!timer)
        return -ENOMEM;

    if (file->private_data && file->private_data != timer) {
        snd_timer_close(file->private_data);
    }

    file->private_data = timer;

    if (tselect.queues == 0)
        tselect.queues = 1;

    if (tselect.channels == 0)
        tselect.channels = 1;

    timer->queues_alloc = tselect.queues;
    timer->channels_alloc = tselect.channels;

    timer->callback = NULL;
    timer->private_free = NULL;

    timer->flags |= SNDRV_TIMER_FLG_FAST;

    return 0;
}

int select_and_init_timer(struct file *file, struct snd_timer_select __user *_tselect) {
    struct snd_timer_select tselect;
    struct timer_data *private_data = file->private_data;
    int ret;

    if (private_data->timer) {
        close_timer(private_data->timer);
        private_data->timer = NULL;
    }

    if (copy_from_user(&tselect, _tselect, sizeof(tselect)))
        return -EFAULT;

    private_data->timer = create_timer(&tselect);
    if (!private_data->timer)
        return -ENOMEM;

    private_data->queues = kmalloc(sizeof(struct queue) * MAX_QUEUES, GFP_KERNEL);
    if (!private_data->queues) {
        close_timer(private_data->timer);
        private_data->timer = NULL;
        return -ENOMEM;
    }

    init_timer_callbacks(private_data->timer, timer_start, timer_stop, timer_callback);
    private_data->timer->is_fast = 1;

    return 0;
}

int snd_timer_user_select(struct file *file, struct snd_timer_select __user *_tselect) {
    struct snd_timer *timer;
    struct snd_timer_select tselect;
    int err;

    if (copy_from_user(&tselect, _tselect, sizeof(tselect)))
        return -EFAULT;

    timer = snd_timer_new(tselect.card, tselect.id, &tselect);
    if (!timer)
        return -ENOMEM;

    if ((err = snd_timer_init(timer, &tselect)) < 0) {
        snd_timer_free(timer);
        return err;
    }

    file->private_data = timer;
    timer->callback = NULL;
    timer->private_data = NULL;
    timer->flags |= SNDRV_TIMER_FLG_FAST;

    return 0;
}
